//! The port against urlfinderlib itself: `tests/data/cases.json` holds 687 inputs, hand-made and
//! generated by `tests/data/gen_corpus.py` (`python3 gen_corpus.py <dir>`), and what ace3's image
//! answered for each, by `tests/data/oracle.py` and `oracle_lxml.py` run in ace3's dev container
//! (`docker exec -i ace-dev-1 /venv/bin/python3 - <dir> < oracle.py`): `find_urls` with its
//! defaults, with `domain_as_url`, with a `text/plain` mime type and with a base URL and
//! `text/html`, `find_urls_in_text` with and without `domain_as_url`, lxml's `tostring` of the
//! HTML tree in the `html` and `text` methods, and BeautifulSoup's `get_text()`. Exceptions
//! compare by their class's name.

use base64::Engine;
use serde_json::{Value, json};

use crate::{Finder, Magic, find_urls_in_text};

fn result(r: crate::py::PyResult<std::collections::BTreeSet<String>>) -> Value {
    match r {
        Ok(urls) => json!({"output": urls}),
        Err(e) => json!({"error": {"type": e.kind}}),
    }
}

fn expected_without_message(v: &Value) -> Value {
    match v.get("error") {
        Some(e) => json!({"error": {"type": e["type"]}}),
        None => v.clone(),
    }
}

#[test]
fn matches_urlfinderlib_on_every_case() {
    let cases: Value =
        serde_json::from_str(include_str!("../tests/data/cases.json")).expect("the cases read");
    let database = std::fs::read(crate::magic::DATABASE).expect("the magic database");
    let magic = Magic::load(database).expect("libmagic");
    let finder = Finder::new(&magic);
    let mut failures = Vec::new();
    let cases = cases["cases"].as_array().expect("cases");
    for case in cases {
        let name = case["name"].as_str().unwrap_or_default();
        let blob = base64::engine::general_purpose::STANDARD
            .decode(case["input"].as_str().unwrap_or_default())
            .expect("base64");
        let text = ace_pycompat::pystr::decode_utf8_ignore(&blob);
        let base = "https://base.example.com/dir/page.html";
        let got = [
            ("default", result(finder.find_urls(&blob, "", "", false))),
            ("domain", result(finder.find_urls(&blob, "", "", true))),
            ("text", result(find_urls_in_text(&blob, false))),
            ("textdomain", result(find_urls_in_text(&blob, true))),
            (
                "plain",
                result(finder.find_urls(&blob, "", "text/plain", false)),
            ),
            (
                "base",
                result(finder.find_urls(&blob, base, "text/html", false)),
            ),
            ("soup", json!({"output": ace_lxml::soup::get_text(&text)})),
            (
                "lxml",
                match ace_lxml::Document::parse_html(text.as_bytes()) {
                    Ok(doc) => json!({"output": {
                        "html": doc.tostring_html().unwrap_or_default(),
                        "text": String::from_utf8_lossy(&doc.tostring_text().unwrap_or_default()),
                    }}),
                    Err(e) => json!({"error": {"type": "lxml", "message": e.to_string()}}),
                },
            ),
        ];
        for (mode, value) in got {
            let expected = expected_without_message(&case["expected"][mode]);
            let value = if mode == "lxml" {
                value
            } else {
                expected_without_message(&value)
            };
            if value != expected {
                failures.push(format!(
                    "{name} {mode}:\n  python: {expected}\n  port:   {value}"
                ));
            }
        }
    }
    assert!(cases.len() >= 680, "only {} cases", cases.len());
    assert!(
        failures.is_empty(),
        "{} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn child_urls_are_urlfinderlib_s() {
    let mut children =
        crate::child_urls("https://redir.example.com/r?u=https%3A%2F%2Ftarget.example.org%2Fland")
            .expect("no exception");
    children.sort();
    assert_eq!(children, ["https://target.example.org/land"]);
}

/// An `on_demand` finder with a loader that counts its calls, and libmagic loaded or refused.
fn counting(calls: &std::cell::Cell<u32>, refuse: bool) -> impl Fn() -> Result<Magic, String> + '_ {
    move || {
        calls.set(calls.get() + 1);
        if refuse {
            return Err("no database".to_owned());
        }
        Magic::load(std::fs::read(crate::magic::DATABASE).map_err(|e| e.to_string())?)
    }
}

#[test]
fn an_on_demand_finder_given_a_description_loads_no_libmagic() {
    let calls = std::cell::Cell::new(0);
    let load = counting(&calls, true);
    let finder = Finder::on_demand(&load);
    let blob = b"<a href=\"https://a.example.com/x\">x</a>";
    let urls = finder
        .find_urls(blob, "", "HTML document, ASCII text", false)
        .expect("no libmagic needed");
    assert!(urls.contains("https://a.example.com/x"), "{urls:?}");
    assert_eq!(calls.get(), 0);
    assert_eq!(finder.load_error(), None);
}

/// UTF-16 bytes are described again once their NULs are gone, which needs libmagic; the finder
/// loads it once, however many descriptions it makes, and finds what a loaded finder finds.
#[test]
fn an_on_demand_finder_loads_libmagic_once_for_bytes_it_describes() {
    let mut blob = vec![0xff, 0xfe];
    for b in b"<a href=\"https://utf16.example.com/x\">x</a>" {
        blob.extend([*b, 0]);
    }
    let database = std::fs::read(crate::magic::DATABASE).expect("the magic database");
    let magic = Magic::load(database).expect("libmagic");
    for mimetype in [
        "",
        "HTML document, Unicode text, UTF-16, little-endian text",
    ] {
        let calls = std::cell::Cell::new(0);
        let load = counting(&calls, false);
        let finder = Finder::on_demand(&load);
        let urls = finder.find_urls(&blob, "", mimetype, false);
        assert_eq!(
            urls,
            Finder::new(&magic).find_urls(&blob, "", mimetype, false),
            "{mimetype:?}"
        );
        assert!(
            urls.expect("found").contains("https://utf16.example.com/x"),
            "{mimetype:?}"
        );
        assert_eq!(calls.get(), 1, "{mimetype:?}");
    }
}

#[test]
fn an_on_demand_finder_that_cant_load_libmagic_says_why() {
    let calls = std::cell::Cell::new(0);
    let load = counting(&calls, true);
    let finder = Finder::on_demand(&load);
    let error = finder
        .find_urls(b"https://a.example.com/", "", "", false)
        .expect_err("libmagic was needed");
    assert_eq!(error.kind, "OSError");
    assert_eq!(finder.load_error(), Some("no database"));
}
